package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<16)

func readInt() int64 {
	c, err := rd.ReadByte()
	for err == nil && c != '-' && (c < '0' || c > '9') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return 0
	}
	neg := false
	if c == '-' {
		neg = true
		c, err = rd.ReadByte()
	}
	var v int64
	for err == nil && c >= '0' && c <= '9' {
		v = v*10 + int64(c-'0')
		c, err = rd.ReadByte()
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	n, m := int(readInt()), int(readInt())
	a := make([]int64, n*m)
	for i := range a {
		a[i] = readInt()
	}
	idx, answer := 0, a[0]
	// Cells get a global 0-based index along the spiral; even indices are landings.
	visit := func(r, c int) {
		if idx%2 == 0 {
			answer = a[r*m+c]
		}
		idx++
	}
	top, left, bottom, right := 0, 0, n-1, m-1
	for top <= bottom && left <= right {
		for r := top; r <= bottom; r++ { // down
			visit(r, left)
		}
		left++
		for c := left; c <= right; c++ { // right
			visit(bottom, c)
		}
		bottom--
		if left <= right {
			for r := bottom; r >= top; r-- { // up
				visit(r, right)
			}
			right--
		}
		if top <= bottom {
			for c := right; c >= left; c-- { // left
				visit(top, c)
			}
			top++
		}
	}
	fmt.Println(answer)
}
